def compute(vars):
    net_revenue_2015 = vars["v1"]
    retail_electric_price_change = vars["v2"]
    volume_weather_change = vars["v3"]

    value = net_revenue_2015 - retail_electric_price_change - volume_weather_change

    return {
        "value": value,
        "trace": {
            "net_revenue_2015": net_revenue_2015,
            "retail_electric_price_change": retail_electric_price_change,
            "volume_weather_change": volume_weather_change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
